namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = "";
    public string Title { get; set; } = "";
    public string Description { get; set; } = "";
    public int Credits { get; set; }
    public string Schedule { get; set; } = "";
    public string Instructor { get; set; } = "";
    public string InstructorBio { get; set; } = "";
    public string Department { get; set; } = "";
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = "";

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]+$", ErrorMessage = "Student ID must be alphanumeric.")]
    public string StudentId { get; set; } = "";

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _courses = new List<Course>
        {
            new Course
            {
                Id = 1, CourseCode = "CS 101", Title = "Introduction to Computer Science",
                Description = "A broad introduction to the field of computer science. Topics include computational thinking, basic programming in Python, data representation, and an overview of how computers work. No prior programming experience is required.",
                Credits = 4, Schedule = "Mon/Wed/Fri 9:00 AM - 9:50 AM",
                Instructor = "Dr. Alice Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT. She has over 15 years of teaching experience and specializes in introductory programming pedagogy.",
                Department = "Computer Science", IsFeatured = true
            },
            new Course
            {
                Id = 2, CourseCode = "CS 201", Title = "Data Structures",
                Description = "Study of fundamental data structures including arrays, linked lists, stacks, queues, trees, and graphs. Students implement these structures in Java and analyze their time and space complexity.",
                Credits = 4, Schedule = "Tue/Thu 10:30 AM - 11:45 AM",
                Instructor = "Dr. Brian Patel", InstructorBio = "Dr. Patel earned his doctorate from Stanford University. His research focuses on algorithm optimization and he has published extensively in top-tier journals.",
                Department = "Computer Science", IsFeatured = false
            },
            new Course
            {
                Id = 3, CourseCode = "CS 301", Title = "Algorithms",
                Description = "Design and analysis of algorithms including divide and conquer, dynamic programming, greedy algorithms, and graph algorithms. Emphasis on proving correctness and analyzing computational complexity.",
                Credits = 3, Schedule = "Mon/Wed 1:00 PM - 2:15 PM",
                Instructor = "Dr. Brian Patel", InstructorBio = "Dr. Patel earned his doctorate from Stanford University. His research focuses on algorithm optimization and he has published extensively in top-tier journals.",
                Department = "Computer Science", IsFeatured = false
            },
            new Course
            {
                Id = 4, CourseCode = "CS 401", Title = "Machine Learning",
