        <strong>@(CatalogService.GetCourse(Model.CourseId)?.Title)</strong> has been received.</p>
        <p>Student ID: @Model.StudentId</p>
    </div>
    <a href="courses" class="btn btn-primary">Browse More Courses</a>
}
else
{
    <div class="row">
        <div class="col-md-6">
